    sys.stderr.write(msg)
    if not msg.endswith("\n"):
        sys.stderr.write("\n")
    sys.exit(2)

def print_help():
    pn = prog_name()
    txt = HELP_TEMPLATE.replace("{prog}", pn)
    sys.stdout.write(txt)

def print_version():
    sys.stdout.write(VERSION_STR)

# Check for help/version before any other validation (they override errors)
