        before_dashdash.append(a)
    # Check for help/version in before_dashdash, considering short combos and = syntax
    # Priority: help before version? Test --help --version gave help, -V --list-options gave version (but -V before --list-options? Actually -V --list-options gave version, so version before list-options. But help vs version: --help --version gave help. What about --version --help? Likely help as well? Or first encountered? Clap typically shows help if both? Let's test later. For now, if both present, show help.
    has_help = False
