        if a == "--help" or a == "-h":
            has_help = True
        elif a == "--version" or a == "-V":
            has_version = True
        elif a.startswith("--help="):
            # Unexpected value for --help? Clap would error, but does help override? Let's treat as help? Actually test needed.
            # For now, treat as help (to override), but original might error. We'll handle as error? Let's check original behavior for --help=x
