            # For now, mark as help to be safe? Or error? Let's mark as error case and let normal parsing handle it (which will error).
            pass
        elif a.startswith("--version="):
            pass
        elif a.startswith("-") and not a.startswith("--") and len(a) > 2:
            # combined shorts like -hv, -sh, etc. Check if contains h or V
            # But need to handle values: -ofoo, -tfoo, -Lfr, -c... Those are not combos but value-attached. How to distinguish?
            # Shorts that take values: o, t, L, c. Others (f,s,n,v,a,q,l,S,h,V) are bools.
            # For combined like -sv (both bools) => ok. For -ofoo (o takes value, rest is value) => not combo.
            # Clap logic: iterate chars; if char takes value, rest of arg is value (or next arg if rest empty).
            # So -hv => h then v (both bools) => has_help.
            # -ofoo => o with value foo => not help.
            # We need to parse to detect h/V in combo.
            chars = a[1:]
            i = 0
            while i < len(chars):
                ch = chars[i]
                if ch in ('o','t','L','c'):
                    # takes value, rest is value, break
                    break
                elif ch == 'h':
                    has_help = True
                    i += 1
                elif ch == 'V':
                    has_version = True
                    i += 1
                elif ch in ('f','s','n','v','a','q','l','S'):
                    i += 1
                else:
                    # unknown short, break (will error later, but help still overrides? If unknown + help, help wins? Test --help --unknown gave help, so yes. So even with unknown, help wins.
                    i += 1
        elif a == "-h":
            has_help = True
        elif a == "-V":
            has_version = True
    if has_help:
        print_help()
