def strip_yaml_comment(line):
    ins=False; ind=False; esc=False; i=0
    while i < len(line):
        ch=line[i]
        if esc:
            esc=False; i+=1; continue
        if ch=='\\' and ind:
            esc=True; i+=1; continue
        if ch=="'" and not ind:
            if ins:
                if i+1<len(line) and line[i+1]=="'":
                    i+=2; continue
                else:
                    ins=False; i+=1; continue
            else:
                ins=True; i+=1; continue
        if ch=='"' and not ins:
            ind=not ind; i+=1; continue
        if ch=='#' and not ins and not ind:
            if i==0 or line[i-1] in (' ','\t'):
                return line[:i].rstrip()
            else:
                i+=1; continue
        i+=1
    return line.rstrip()

def parse_yaml_scalar(s):
    if s=="" or s is None:
        return ('string','')
    if len(s)>=2 and ((s[0]=='"' and s[-1]=='"') or (s[0]=="'" and s[-1]=="'")):
        q=s[0]; inner=s[1:-1]
        if q=='"':
            res=[]; i=0
            while i<len(inner):
                if inner[i]=='\\' and i+1<len(inner):
                    nxt=inner[i+1]
                    if nxt=='"':
                        res.append('"'); i+=2; continue
                    elif nxt=='\\':
                        res.append('\\'); i+=2; continue
                    elif nxt=='n':
                        res.append('\n'); i+=2; continue
                    elif nxt=='t':
                        res.append('\t'); i+=2; continue
                    else:
                        res.append(nxt); i+=2; continue
                else:
                    res.append(inner[i]); i+=1
            return ('string',''.join(res))
        else:
            i=0; res=[]; valid=True
            while i<len(inner):
                if inner[i]=="'":
                    if i+1<len(inner) and inner[i+1]=="'":
                        res.append("'"); i+=2; continue
                    else:
                        valid=False; break
                else:
                    res.append(inner[i]); i+=1
            if not valid:
                return ('yaml_error',"while parsing a block mapping, did not find expected key")
            return ('string',''.join(res))
    if s=="true":
        return ('bool',True)
    if s=="false":
        return ('bool',False)
    if s in ("null","Null","NULL","~"):
