def render_jinja_simple(template, ctx):
    import re as re2
    while True:
        m=re2.search(r'{%\s*endif\s*%}',template)
        if not m:
            break
        es,ee=m.span()
        prefix=template[:es]
        ifs=list(re2.finditer(r'{%\s*if\s+(\S+)\s*%}',prefix))
        if not ifs:
            template=template[:es]+template[ee:]
            continue
        last=ifs[-1]
        var=last.group(1)
        ss,se=last.span()
        inner=template[se:es]
        cond=bool(ctx.get(var,False))
        repl=inner if cond else ""
        template=template[:ss]+repl+template[ee:]
    def vr(m):
        return str(ctx.get(m.group(1).strip(),""))
    template=re.sub(r'{{\s*(.*?)\s*}}',vr,template)
    return template
def render_tex_simple(template, ctx):
    import re as re2
    while True:
        m=re2.search(r'<#\s*endif\s*#>',template)
        if not m:
            break
        es,ee=m.span()
        prefix=template[:es]
        ifs=list(re2.finditer(r'<#\s*if\s+(.*?)\s*#>',prefix))
        if not ifs:
            template=template[:es]+template[ee:]
            continue
        last=ifs[-1]
        cond_str=last.group(1).strip()
        ss,se=last.span()
        inner_full=template[se:es]
        me=re2.search(r'<#\s*else\s*#>',inner_full)
        if me:
            es2,ee2=me.span()
            tp=inner_full[:es2]; fp=inner_full[ee2:]
        else:
            tp=inner_full; fp=""
        if cond_str.startswith('not '):
            var=cond_str[4:].strip()
            cond=not bool(ctx.get(var,False))
        else:
            cond=bool(ctx.get(cond_str,False))
        repl=tp if cond else fp
        template=template[:ss]+repl+template[ee:]
    template=re2.sub(r'<<(.+?)>>',lambda m: str(ctx.get(m.group(1),"")),template)
    return template
